insert into public.limpieza_rutinas(codigo,aposento_id,nombre,activo)
select d.codigo,a.id,d.nombre,d.activo from data d join public.limpieza_aposentos a on a.slug=d.aposento_slug
on conflict(codigo) do update set aposento_id=excluded.aposento_id,nombre=excluded.nombre,activo=excluded.activo;

