insert into public.limpieza_programacion(
  turno_codigo,conserje_id,aposento_id,rutina_id,dia_semana,hora_inicio,hora_fin,
  foto_requerida,vigente_desde,vigente_hasta
)
select d.turno_codigo,c.id,a.id,r.id,d.dia_semana,d.hora_inicio,d.hora_fin,d.foto_requerida,d.vigente_desde,d.vigente_hasta::date
from data d join public.limpieza_conserjes c on c.nombre=d.conserje
join public.limpieza_aposentos a on a.slug=d.aposento_slug
join public.limpieza_rutinas r on r.codigo=d.rutina_codigo and r.aposento_id=a.id
on conflict(turno_codigo) where turno_codigo is not null do update set
  conserje_id=excluded.conserje_id,aposento_id=excluded.aposento_id,rutina_id=excluded.rutina_id,
  dia_semana=excluded.dia_semana,hora_inicio=excluded.hora_inicio,hora_fin=excluded.hora_fin,
  foto_requerida=excluded.foto_requerida,vigente_desde=excluded.vigente_desde,vigente_hasta=excluded.vigente_hasta;

do $$
begin
  if (select count(*) from public.limpieza_programacion where turno_codigo like 'excel-%') <> 212 then
    raise exception 'La carga de programación no produjo 212 turnos';
  end if;
  if (select count(*) from public.limpieza_rutina_labores rl join public.limpieza_rutinas r on r.id=rl.rutina_id where r.codigo in ('areas-comunes-r1','aula-708-r1','aula-709-r1','aula-710-r1','aula-711-r1','bodega-equipo-r1','cocina-cubiculos-profesores-r1','cocina-cubiculos-profesores-r2','cocina-oficina-administrativa-r1','cocina-oficina-administrativa-r2','cubiculos-profesores-r1','gradas-ii-piso-geografia-r1','herbario-r1','laboratorio-de-computo-r1','laboratorio-de-ecologia-r1','laboratorio-de-hidrogeologia-r1','laboratorio-l602-r1','laboratorio-l603-r1','oficina-del-herbario-r1','oficinas-administrativas-r1','pasillo-ii-piso-aulas-r1','pasillos-i-piso-barandas-y-gradas-r1','pasillos-i-piso-barandas-y-gradas-r2','pasillos-ii-piso-barandas-y-gradas-r1','pasillos-iii-piso-barandas-y-gradas-r1','pollitos-del-jardin-r1','procame-r1','jaulas-basura-r1','jaulas-basura-r2','sala-de-sesiones-r1','servicios-sanitarios-estudiantes-mixto-ii-piso-r1','servicios-sanitarios-funcionarias-mujeres-i-piso-r1','servicios-sanitarios-estudiantes-mujeres-iii-piso-r1','servicios-sanitarios-estudiantes-mujeres-iii-piso-r2','servicios-sanitarios-funcionarios-varones-iii-piso-r1','vivero-forestal-r1','oficina-de-adrian-r1')) <> 194 then
    raise exception 'La carga de labores no produjo 194 asignaciones';
  end if;
end $$;
